actions.action:
// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate NY state additions
            double additions = 0.0;

            // NY adds back interest on U.S. government obligations
            // (exempt from federal tax but taxable to NY)
            // additions += revenue.federal_bond_interest;

            // NY adds back IRC 199A deduction (state doesn't conform)
            // additions += result.section_199a_deduction;

            // NY may require depreciation adjustments
            // additions += result.ny_depreciation_addback;

            apportionment.state_additions = additions;

            // Calculate NY state subtractions
            double subtractions = 0.0;

            // NY allows subtraction for interest on NY/local government bonds
            // subtractions += revenue.ny_municipal_interest;

            // Qualified emerging technology company (QETC) deductions
            // subtractions += result.ny_qetc_deduction;

            apportionment.state_subtractions = subtractions;

            // NY uses flat 6.5% rate (Tax Law § 209)
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract NY state credits
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // MTA surcharge will be added in table 50190 if applicable
            // For now, calculate base refund/owed (will be adjusted by MTA surcharge)
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

            // MTA surcharge is 0.34% of business income base
            result.ny_mta_surcharge =
              apportionment.state_taxable_income * result.ny_mta_surcharge_rate;

            // Add MTA surcharge to total state tax
            apportionment.state_tax = apportionment.state_tax + result.ny_mta_surcharge;

            // Recalculate refund or amount owed including MTA surcharge
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
